-- =====================================================================
-- Les champs du moteur : contexte, capacites, livrables, cadrage.
--
-- Ni titre, ni categorie, ni collection, ni ordre. Le classeur porte encore
-- la taxonomie d'avant le rangement des rayons ; les ecrire deferait ce qui
-- a ete valide et deploye depuis. Seule la matiere entre.
-- =====================================================================

update public.prompts set contexte = 'Souvenir artistique, projection d’âge ou portrait historique personnel. Usage précis : Ancêtre imaginaire.', specification = 'Choisir une époque et un lieu déclarés ; costume, coiffure et procédé photographique doivent appartenir au même contexte, sans prétendre retrouver un ancêtre réel.', livrables = '1 image finale ; meilleure résolution réellement disponible, dimensions annoncées seulement si vérifiées', questions_cadrage = 'Si une information indispensable manque, poser une seule question ciblée sur : Époque, âge cible si pertinent, lieu et référence de la personne. Proposer une option créative raisonnable pour les préférences secondaires, sans bloquer la production.', criteres_reussite = 'Choisir une époque et un lieu déclarés ; costume, coiffure et procédé photographique doivent appartenir au même contexte, sans prétendre retrouver un ancêtre réel. Contrôle commun : fidélité des références, lisibilité à taille d’usage, proportions, lumière, absence d’artefacts et exactitude des textes.', erreurs = 'Les scènes non documentées sont des évocations artistiques, jamais des archives authentiques. Ne pas livrer une simple description si la génération est disponible.', regle_sortie = 'Commande ponctuelle : livrer le résultat puis attendre une demande de variante.' where card_id = 'img-ancestorportrait';
