update public.prompts set contexte = 'Production guidée d’un ensemble cohérent : Annonce seconde main fidèle.', specification = 'Exiger vue globale, détail et zones d’usure du même article. Conserver marques d’usage dans les trois fichiers. Améliorer seulement lumière, cadrage et fond. Ne pas reconstruire une face cachée pour la vente.', livrables = '3 livrables : Vue globale nettoyée [4:5]; Détail réel [1:1]; État et usure [4:5].', questions_cadrage = 'Quel article vends-tu, sur quel canal, et quels défauts faut-il montrer ? Puis compléter les données indispensables une à une avant la production concernée.', criteres_reussite = 'Vérifier exactement 3 livrables, leur correspondance au brief, textes identiques entre formats, mêmes sujets et actifs, dimensions réellement produites et absence de fichiers manquants. Les planches réutilisent les rendus validés.', erreurs = 'Ne pas remplacer les fichiers individuels par une seule planche ; ne pas modifier identité, produit ou textes entre livrables ; ne pas annoncer un lot complet si un outil ou une référence manque.', regle_sortie = 'Pause : récapituler les éléments validés et la prochaine étape. Reprise : repartir de ce point. Arrêter : lister fichiers terminés et restants.' where card_id = 'path-packresale';
